-- Catálogo Coproactiva v1.0 (octubre de 2026).
-- 33 plantillas, agrupadas en 7 áreas; la plantilla 08 conserva su variante B.
-- La sección H del documento describe avisos automáticos, no plantillas manuales.
-- No se reemplazan plantillas de usuarios; los inserts son idempotentes.
alter table public.plantillas_correo_crm
 add column if not exists codigo text,
 add column if not exists categoria text,
 add column if not exists uso text,
 add column if not exists etapa_crm text,
 add column if not exists adjunto_sugerido text,
 add column if not exists sugerida boolean not null default false,
 add column if not exists variantes jsonb not null default '[]'::jsonb;
create unique index if not exists plantillas_correo_crm_codigo_unico
 on public.plantillas_correo_crm(codigo);

insert into public.plantillas_correo_crm (codigo,nombre,categoria,uso,etapa_crm,adjunto_sugerido,asunto,cuerpo,sugerida,variantes,activa)
select x.codigo,x.nombre,x.categoria,x.uso,x.etapa_crm,x.adjunto_sugerido,x.asunto,x.cuerpo,x.sugerida,x.variantes,true
from jsonb_to_recordset('[{"codigo":"01","nombre":"Primer contacto con comité","categoria":"Captación","uso":"después de una llamada o WhatsApp con un comité o presidente.","etapa_crm":"Prospecto → Contactado","adjunto_sugerido":"PRESENTACIÓN - COPROACTIVA.pdf","asunto":"Coproactiva — Administración profesional para {{comunidad}}","cuerpo":"{{saludo}} {{nombre}}:\n\nJunto con saludar, y de acuerdo a lo conversado, envío este correo a modo de presentación de nuestros servicios.\n\nEn Coproactiva diagnosticamos antes de administrar. Trabajamos para que el comité no tenga que perseguir respuestas ni terminar resolviendo tareas que corresponden a la administración: ordenamos la gestión diaria y explicamos con claridad qué se hizo, qué sigue pendiente y quién está a cargo.\n\nSomos una administración certificada, con inscripción vigente en el Registro Nacional de Administradores de Condominios del MINVU. Puede verificarlo en el portal oficial: https://condominios.minvu.cl/\n\nPara evaluar mejor la realidad de la comunidad, proponemos reunirnos {{modalidad}} el {{fecha}} a partir de las {{hora}}. Quedamos atentos a vuestra confirmación.\n\n[Opcional] Para tener una evaluación general previa, le agradeceríamos enviarnos la última liquidación de gastos comunes.\n\nUn cordial saludo.","sugerida":false,"variantes":[]},{"codigo":"02","nombre":"Prospección a inmobiliaria (en frío)","categoria":"Captación","uso":"primer contacto con inmobiliarias con proyectos nuevos. Priorizar correo de casa matriz por sobre sala de ventas.","etapa_crm":"Prospecto → Contactado","adjunto_sugerido":"PRESENTACIÓN - COPROACTIVA.pdf","asunto":"Administración de comunidades en {{comuna}} — Coproactiva","cuerpo":"Estimad@s:\n\nMi nombre es {{remitente}}, de Coproactiva, empresa de administración de edificios y comunidades con base en San Bernardo.\n\nNos contactamos porque conocemos sus proyectos en {{comuna}}, como {{proyecto}}, y trabajamos justamente en el tipo de acompañamiento que requieren los condominios nuevos bajo la Ley N.º 21.442.\n\nNuestros servicios:\n\n• Primera administración para proyectos nuevos: definimos procesos, orden financiero, estructura operativa y coordinación de proveedores para que la comunidad parta funcionando de forma clara y sostenible.\n\n• Administración de edificios y comunidades: gestión integral con orden financiero, control operativo y cumplimiento normativo.\n\n• Auditorías y asesorías: evaluación de la gestión vigente, identificación de brechas y lineamientos concretos de mejora.\n\nAdjuntamos nuestra presentación institucional. Quedamos a vuestra disposición para coordinar una reunión y revisar cómo podemos aportar a sus proyectos en {{comuna}}.\n\nUn cordial saludo.","sugerida":false,"variantes":[]},{"codigo":"03","nombre":"Solicitud entrante: pedir antecedentes","categoria":"Captación","uso":"un comité o presidente pide propuesta por correo o formulario web.","etapa_crm":"Lead entrante → Calificación","adjunto_sugerido":"","asunto":"Re: [asunto original]","cuerpo":"{{saludo}} {{nombre}}:\n\nJunto con saludar, agradecemos su interés en Coproactiva. Con gusto podemos evaluar una propuesta de administración para su comunidad.\n\nPara ello, le agradeceríamos compartirnos la siguiente información:\n\n- Nombre y dirección de la comunidad (comuna).\n- Número de unidades (departamentos o casas, estacionamientos y bodegas) y cantidad de torres o pisos.\n- Principales instalaciones y equipamiento (ascensores, bombas, piscina, quincho, gimnasio, grupo electrógeno, etc.).\n- Situación actual de la administración y plazo estimado para el cambio.\n- Última liquidación de gastos comunes, si la tiene disponible.\n\nQuedamos a vuestra disposición.\n\nSaludos cordiales,","sugerida":false,"variantes":[]},{"codigo":"04","nombre":"Envío de presentación y propuesta de reunión","categoria":"Captación","uso":"el prospecto ya envió los antecedentes de la plantilla 03.","etapa_crm":"Calificación → Reunión por agendar","adjunto_sugerido":"PRESENTACIÓN - COPROACTIVA.pdf","asunto":"Re: [asunto original]","cuerpo":"{{saludo}} {{nombre}}:\n\nMuchas gracias por compartir la información.\n\nAdjunto encontrará nuestra presentación corporativa, donde podrá conocer más sobre la administración integral que ofrecemos en Coproactiva.\n\nPara revisar los detalles del servicio y definir los pasos a seguir, le proponemos una reunión. Contamos con la siguiente disponibilidad:\n\n- Videollamada: {{disponibilidad_online}}.\n- Presencial en {{comunidad}}: {{disponibilidad_presencial}}.\n\nLe agradeceríamos también un número de teléfono para coordinar con mayor agilidad.\n\nQuedamos atentos a sus comentarios para coordinar la alternativa de su preferencia.\n\nSaludos cordiales,","sugerida":false,"variantes":[]},{"codigo":"05","nombre":"Respuesta a comité que evalúa cambio de administración","categoria":"Captación","uso":"el comité envía una solicitud formal con requisitos o preguntas específicas.","etapa_crm":"Lead entrante → Propuesta en preparación","adjunto_sugerido":"PRESENTACIÓN - COPROACTIVA.pdf","asunto":"Re: [asunto original]","cuerpo":"Estimados miembros del Comité de Administración de {{comunidad}}:\n\nAgradecemos la oportunidad de presentar nuestra propuesta y les confirmamos nuestra disponibilidad para asumir la administración de su comunidad.\n\nContamos con un equipo que integra profesionales en contabilidad, auditoría, sistemas y área técnica, lo que nos permite asegurar transparencia y control financiero y operacional. Disponemos además de herramientas de diagnóstico para entregar una asesoría integral desde el primer día, y nos adaptamos a las plataformas digitales que utilice la comunidad.\n\n[Responder aquí cada punto solicitado por el comité: servicios incluidos, frecuencia de visitas, equipo asignado, valor mensual, costos adicionales, plataformas.]\n\nQuedamos a vuestra disposición para coordinar una reunión presencial o virtual, conocer las necesidades de la comunidad y revisar en detalle nuestra propuesta de trabajo.\n\nSaludos cordiales,","sugerida":false,"variantes":[]},{"codigo":"06","nombre":"Fuera de cobertura: declinar y ofrecer alternativa","categoria":"Captación","uso":"la comunidad está fuera de la zona de operación.","etapa_crm":"Lead entrante → Descartado (o Servicio acotado)","adjunto_sugerido":"","asunto":"Solicitud recibida — {{comunidad}}","cuerpo":"{{saludo}} {{nombre}}:\n\nJunto con saludar, agradecemos su solicitud y el detalle entregado sobre la comunidad.\n\nLe comentamos con transparencia que, por el momento, la ubicación del condominio se encuentra fuera de nuestro rango de cobertura para el servicio de administración, por lo que no estaríamos en condiciones de presentar una propuesta que asegure el estándar de gestión y presencia que ofrecemos.\n\nNo obstante, sí podemos apoyarlos en dos servicios acotados que suelen ser de utilidad para un comité que evalúa un cambio de administración:\n\n- Auditoría contable: revisión de la gestión financiera, respaldo de gastos, fondos y obligaciones económicas.\n- Diagnóstico inicial: levantamiento del estado real del condominio en materia operativa, normativa y documental, con lineamientos concretos de mejora.\n\nSi el comité lo estima pertinente, quedamos a vuestra disposición para coordinar una reunión y explicar el alcance de cualquiera de estas alternativas.\n\nUn cordial saludo.","sugerida":false,"variantes":[]},{"codigo":"07","nombre":"Coordinación de reunión con antecedentes a revisar","categoria":"Reuniones","uso":"reunión ya acordada por teléfono o WhatsApp; especialmente para primera administración.","etapa_crm":"Reunión agendada","adjunto_sugerido":"PRESENTACIÓN - COPROACTIVA.pdf","asunto":"Reunión {{fecha}} — {{comunidad}}","cuerpo":"{{saludo}} {{nombre}}:\n\nTal como acordamos, le escribo para coordinar los detalles de nuestra reunión del {{fecha}}, a las {{hora}}, {{modalidad}}.\n\nAdjunto la presentación de Coproactiva para que puedan conocer más sobre nosotros y anotar sus dudas. Durante la reunión revisaremos en detalle los temas que nos mencionó: {{temas}}.\n\n[Si es proyecto nuevo] Al tratarse de un condominio nuevo, es indispensable revisar los antecedentes de origen. Si cuentan con los siguientes documentos, les agradeceríamos enviárnoslos con anticipación; de lo contrario, podemos revisarlos juntos en la reunión:\n\nDocumentos de la inmobiliaria y recepción\n- Reglamento de copropiedad inscrito en el CBR\n- Certificado de copropiedad\n- Permiso de edificación y recepción definitiva (total o por etapas)\n- Planos archivados y tabla de prorrateo\n\nDocumentos técnicos\n- Certificaciones de instalaciones (eléctrica, gas, ascensores, bombas, etc.)\n- Plan de emergencia y evacuación\n- Manuales, garantías y contactos de proveedores de bienes comunes\n\nDocumentos de administración\n- Designación y contrato de la administración actual\n- Estado de venta de las unidades\n- Presupuesto, gastos comunes emitidos y cuenta bancaria\n- Personal contratado y proveedores vigentes\n\nPor último, ¿podría indicarnos quiénes asistirán a la reunión por parte de la comunidad?\n\nQuedamos atentos a sus comentarios.\n\nSaludos cordiales,","sugerida":false,"variantes":[]},{"codigo":"08","nombre":"Confirmación de reunión","categoria":"Reuniones","uso":"el contacto propone o acepta fecha. Dos variantes.","etapa_crm":"Reunión agendada","adjunto_sugerido":"","asunto":"Re: [asunto original]","cuerpo":"{{saludo}} {{nombre}}:\n\nNingún problema, quedamos coordinados para el {{fecha}} a las {{hora}}.\n\nUn cordial saludo.","sugerida":false,"variantes":[{"nombre":"B — con invitación","cuerpo":"{{saludo}} {{nombre}}:\n\nBuenas tardes. Perfecto, ya realizamos el agendamiento según lo indicado; igualmente compartimos la invitación por este medio:\n\n{{titulo_reunion}}\n{{fecha}} · {{hora}} (hora de Santiago)\nEnlace: {{enlace_videollamada}}\n\nUn cordial saludo."}]},{"codigo":"09","nombre":"Resumen de reunión: acuerdos y próximos pasos","categoria":"Reuniones","uso":"el mismo día o al día siguiente de cada reunión con cliente o prospecto.","etapa_crm":"cualquier etapa (registrar como actividad)","adjunto_sugerido":"documentos comprometidos en la reunión","asunto":"Resumen reunión {{comunidad}} – {{fecha}}","cuerpo":"{{saludo}} {{nombre}}:\n\nJunto con saludar, y agradeciendo la reunión del {{fecha}}, dejo por escrito los principales acuerdos y los antecedentes que necesitamos para avanzar.\n\nAcuerdos:\n\n- {{tema_1}}: {{acuerdo_1}}\n- {{tema_2}}: {{acuerdo_2}}\n- {{tema_3}}: {{acuerdo_3}}\n\nPróximos pasos:\n\n- {{empresa}}: {{tareas_cliente}}\n- Coproactiva: {{tareas_coproactiva}}\n\n[Si aplica] Documentación pendiente:\n\n- {{documento_1}}\n- {{documento_2}}\n\nAdjunto {{documentos_adjuntos}} para su revisión.\n\nQuedamos atentos a sus comentarios.\n\nSaludos cordiales,","sugerida":false,"variantes":[]},{"codigo":"10","nombre":"Envío de propuesta de administración integral","categoria":"Propuesta y dudas comerciales","uso":"tras diagnóstico, reunión o recepción de antecedentes.","etapa_crm":"Propuesta enviada","adjunto_sugerido":"Propuesta Administración Integral - {{comunidad}}.pdf","asunto":"Re: [asunto original] — o — Propuesta de administración {{comunidad}}","cuerpo":"{{saludo}} {{nombre}}:\n\nJunto con saludar, y de acuerdo a lo conversado, adjunto nuestra propuesta de administración integral para {{comunidad}}.\n\nLa propuesta fue elaborada a partir de las prioridades planteadas: {{prioridades}}. En ella detallamos el alcance de nuestros servicios conforme al artículo 20 de la Ley N.° 21.442, el plan de levantamiento inicial, los tiempos de respuesta, la propuesta económica y los próximos pasos.\n\n[Si es primera administración] La propuesta incluye nuestro plan de puesta en marcha, pensado para avanzar con agilidad considerando la proximidad de la primera entrega de unidades.\n\nAnte cualquier consulta, o si desean revisar algún punto en detalle, quedamos a vuestra disposición para coordinar una reunión.\n\nUn cordial saludo.","sugerida":false,"variantes":[]},{"codigo":"11","nombre":"Envío de cotización breve","categoria":"Propuesta y dudas comerciales","uso":"el detalle ya se conversó y solo falta formalizar por escrito.","etapa_crm":"Propuesta enviada","adjunto_sugerido":"Propuesta comercial + PRESENTACIÓN - COPROACTIVA.pdf","asunto":"Cotización y presentación corporativa – Coproactiva","cuerpo":"{{saludo}} {{nombre}}:\n\nJunto con saludar, le escribimos para hacer entrega de la cotización, elaborada conforme a los datos proporcionados en nuestra conversación, junto con nuestra presentación corporativa.\n\nEsperamos vuestros comentarios para avanzar.\n\nQuedamos a vuestra disposición ante cualquier consulta.\n\nSaludos cordiales,","sugerida":false,"variantes":[]},{"codigo":"12","nombre":"Propuesta actualizada (nueva versión)","categoria":"Propuesta y dudas comerciales","uso":"cambia el alcance (unidades, etapas, servicios) o el cliente pide valores adicionales.","etapa_crm":"Negociación","adjunto_sugerido":"Propuesta {{comunidad}} v{{version}}.pdf","asunto":"Propuesta comercial {{comunidad}} v{{version}}","cuerpo":"{{saludo}} {{nombre}}:\n\nJunto con saludar, le envío adjunta nuestra propuesta actualizada para {{comunidad}}, considerando {{cambio}}.\n\n{{explicacion_ajuste}}\n[Ej. sin ajuste: \"Mantuvimos el honorario sin ajuste por esta incorporación. Al tratarse de unidades que se integran al mismo conjunto, podemos absorberlas dentro de nuestra estructura de gestión.\"]\n[Ej. con ajuste: \"La propuesta detalla los tramos de honorarios para cada etapa del proyecto.\"]\n\n[Si se busca avanzar] Si les parece bien la propuesta, para continuar necesitaríamos:\n\n1. {{requisito_1}}\n2. {{requisito_2}}\n3. Datos para el contrato: razón social, RUT y domicilio, además del nombre y RUT del representante legal.\n\nQuedo atento a sus comentarios.\n\nUn cordial saludo.","sugerida":false,"variantes":[]},{"codigo":"13","nombre":"Aclaración de honorario por etapas","categoria":"Propuesta y dudas comerciales","uso":"el cliente consulta a qué corresponde el valor propuesto.","etapa_crm":"Negociación","adjunto_sugerido":"propuesta corregida (si aplica)","asunto":"Re: [asunto original]","cuerpo":"{{saludo}} {{nombre}}:\n\nMuy buen día. Correcto, el honorario de {{honorario_etapa_1}} corresponde a la administración de la {{etapa_1}}, esto es, las {{unidades_etapa_1}} unidades actualmente recepcionadas.\n\nAl obtenerse la recepción definitiva de la {{etapa_2}}, quedando el condominio completo en {{unidades_total}} unidades, el honorario se ajusta a {{honorario_total}} mensuales. Este valor contempla el acta de recepción de los bienes comunes de la nueva etapa y la incorporación de las nuevas unidades a la gestión de cobranza, manteniendo el resto del alcance descrito en la propuesta.\n\nPara mayor claridad, dejamos adjunta la propuesta corregida con el detalle de las etapas.\n\nQuedamos atentos a sus comentarios.\n\nSaludos cordiales.","sugerida":false,"variantes":[]},{"codigo":"14","nombre":"Solicitud de rebaja o periodo de prueba","categoria":"Propuesta y dudas comerciales","uso":"el cliente pide un valor menor los primeros meses.","etapa_crm":"Negociación","adjunto_sugerido":"Contrato_Administracion_Integral.pdf (si lo solicitan)","asunto":"Re: [asunto original]","cuerpo":"{{saludo}} {{nombre}}:\n\nJunto con saludar, y respecto de su consulta, le confirmamos que nuestra propuesta de administración integral va respaldada por un contrato de prestación de servicios detallado, el cual compartimos adjunto para su revisión.\n\nEn relación con la posibilidad de aplicar un valor menor durante los primeros meses, no estamos en condiciones de ofrecer rebajas temporales. Si en algún momento nuestro servicio no cumple con lo esperado, el comité siempre tiene la posibilidad de dar término a la administración, por lo que el valor propuesto responde directamente al nivel de servicio comprometido desde el inicio.\n\nA esto se suma que los primeros tres meses son los que concentran la mayor carga de trabajo: es el período en que se realizan los levantamientos, las regularizaciones y la definición de los planes de acción que ordenan la gestión del condominio. Por eso el valor se mantiene estable desde el inicio y no responde a una etapa de prueba.\n\nQuedamos a vuestra disposición para resolver cualquier duda adicional o coordinar una reunión con el comité.\n\nUn cordial saludo.","sugerida":false,"variantes":[]},{"codigo":"15","nombre":"Presupuesto del cliente bajo el mínimo","categoria":"Propuesta y dudas comerciales","uso":"el cliente fija un tope de pago o reduce el alcance por debajo de lo que exige la ley.","etapa_crm":"Negociación","adjunto_sugerido":"","asunto":"Re: [asunto original]","cuerpo":"{{saludo}} {{nombre}}:\n\nGracias por la información. Le respondo con transparencia, porque hay algo que conviene aclarar antes de hablar de cifras.\n\nLa administración de un condominio es una prestación de servicios profesionales cuyo contenido está definido por la Ley N.° 21.442 y su reglamento. El comité elige a quién le encarga esa función, pero las obligaciones que la componen están fijadas por ley.\n\nSe lo comento porque los protege a ustedes: si el alcance se define por debajo de lo que la norma exige, quien queda expuesto es el comité. En lo que nos enviaron no aparecen recogidas algunas obligaciones legales, como {{obligaciones_faltantes}}.\n[Ej.: la rendición mensual documentada ante el comité, el presupuesto anual o la vigencia del plan de evacuación.]\n\nSobre esa base sí corresponde conversar el honorario y las condiciones. Nuestra base de administración es de {{honorario_base}}, un monto de partida que podría ajustarse según el diagnóstico inicial, donde levantamos las principales necesidades, el tipo de instalaciones y su estado, el cumplimiento normativo y el control documental.\n\nEs el modelo que proponemos para seguridad de ambas partes, de modo que la propuesta y sus alcances queden definidos desde el primer día.\n\nPor nuestra parte, toda la disponibilidad para avanzar. Quedamos atentos.\n\nSaludos cordiales.","sugerida":false,"variantes":[]},{"codigo":"16","nombre":"Consulta técnica con estimación preliminar","categoria":"Propuesta y dudas comerciales","uso":"el cliente pide una cifra (gasto común, valor por m², fondo operacional) antes de tener todos los antecedentes.","etapa_crm":"Negociación / Puesta en marcha","adjunto_sugerido":"","asunto":"Re: [asunto original]","cuerpo":"{{saludo}} {{nombre}}:\n\nJunto con saludar, gracias por su consulta.\n\nCon los antecedentes que tenemos a la fecha, estimamos {{concepto}} del orden de {{rango_estimado}}.\n\nLe explico cómo llegamos a esa cifra: {{explicacion_calculo}}\n[Ej. gasto común: \"El gasto común no se fija por unidad: se presupuesta el costo total de operación de la comunidad y se distribuye según la tabla de prorrateo, construida a partir de la superficie de cada unidad.\"]\n\nEs una estimación preliminar. Faltan antecedentes que inciden directamente en el cálculo:\n\n- {{antecedente_1}}\n- {{antecedente_2}}\n- {{antecedente_3}}\n\nLa cifra formal se elabora {{condicion}} [Ej.: una vez formalizada la designación y con esos antecedentes a la vista]. Es la única forma de entregar un valor que se sostenga, considerando que los copropietarios lo reciben como un compromiso.\n\nQuedamos a vuestra disposición para revisar cualquier punto que necesiten ir definiendo.\n\nSaludos cordiales,","sugerida":false,"variantes":[]},{"codigo":"17","nombre":"Adjudicación y borrador de contrato","categoria":"Cierre y puesta en marcha","uso":"el cliente confirma que elige a Coproactiva.","etapa_crm":"Ganado → Contrato en revisión","adjunto_sugerido":"Borrador de contrato de administración","asunto":"Re: [asunto original]","cuerpo":"{{saludo}} {{nombre}}:\n\nMuchas gracias por la confianza. Nos alegra mucho poder acompañarlos en {{comunidad}}.\n\nPara agilizar el proceso, adjuntamos el borrador de nuestro contrato de administración. Ya incluye lo conversado en la propuesta: {{puntos_clave}} [Ej.: la puesta en marcha, la incorporación de etapas, los tiempos de respuesta y la transición hacia el comité]. Así solo tienen que revisarlo y hacernos llegar sus comentarios.\n\n[Si es primera administración] En los próximos días les enviaremos también el borrador de la escritura de designación del primer administrador.\n\nPara completar ambos documentos, necesitaríamos:\n\n1. Quién firmará por {{empresa}} y copia de su personería vigente.\n2. Nombre, cargo y correo de la persona que será nuestra contraparte mientras no exista comité: quien aprobará el presupuesto y las contrataciones, y autorizará los pagos de la comunidad.\n3. Una fecha para la firma. Si les acomoda, podemos ir a sus oficinas.\n\nTambién nos gustaría coordinar una reunión para definir algunos puntos de la puesta en marcha, como {{temas_reunion}}. ¿Qué día les acomoda?\n\nSaludos cordiales,","sugerida":false,"variantes":[]},{"codigo":"18","nombre":"Envío de antecedentes legales de la empresa","categoria":"Cierre y puesta en marcha","uso":"el cliente o su área legal solicita documentación de Coproactiva.","etapa_crm":"Contrato en revisión","adjunto_sugerido":"Estatutos · Vigencia · CI representante legal · Resolución Registro Nacional de Administradores (MINVU)","asunto":"Re: [asunto original]","cuerpo":"{{saludo}} {{nombre}}:\n\nBuenas tardes. Junto con saludar, adjuntamos la documentación legal solicitada para la revisión de su área jurídica:\n\n- Estatutos y constitución de la sociedad.\n- Certificado de vigencia.\n- Cédula de identidad del representante legal.\n- Copia de la resolución del Registro Nacional de Administradores del MINVU.\n\nAsimismo, detallamos los antecedentes de la empresa:\n\n- Razón social: {{razon_social}}\n- RUT: {{rut_empresa}}\n- Domicilio: {{domicilio_empresa}}\n- Representante legal: {{rep_legal_nombre}}\n- RUT representante legal: {{rep_legal_rut}}\n\nQuedamos a vuestra disposición ante cualquier consulta adicional.\n\nSaludos cordiales,","sugerida":false,"variantes":[]},{"codigo":"19","nombre":"Acuse de recepción de documentos","categoria":"Cierre y puesta en marcha","uso":"el cliente envía antecedentes y se revisaron.","etapa_crm":"Puesta en marcha","adjunto_sugerido":"Seguimiento Coproactiva - {{comunidad}}.pdf (si aplica)","asunto":"Re: [asunto original]","cuerpo":"{{saludo}} {{nombre}}:\n\nJunto con saludar, le confirmamos que recibimos y evaluamos la documentación enviada.\n\nAdjunto le hacemos llegar el documento de seguimiento, donde formalizamos la recepción de los antecedentes y detallamos los puntos pendientes de evaluación.\n\nAdicionalmente, proponemos una reunión {{modalidad}} el {{fecha}} a las {{hora}}, con el objeto de revisarlo en conjunto y coordinar los próximos pasos.\n\nQuedamos a vuestra disposición.\n\nSaludos cordiales,","sugerida":false,"variantes":[]},{"codigo":"20","nombre":"Solicitud de documentación pendiente","categoria":"Cierre y puesta en marcha","uso":"levantamiento documental de primera administración o cambio de administración. Borrar lo que ya se recibió.","etapa_crm":"Puesta en marcha","adjunto_sugerido":"","asunto":"Documentación requerida — {{comunidad}}","cuerpo":"{{saludo}} {{nombre}}:\n\nJunto con saludar, y con el fin de avanzar en el levantamiento documental de {{comunidad}}, le compartimos los antecedentes que tenemos y los que aún necesitamos.\n\nRecibidos:\n- {{documentos_recibidos}}\n\nPendientes:\n- Permiso de edificación y certificado de recepción definitiva.\n- Certificados técnicos de bienes comunes: eléctricos (TE1), gas y sanitarios.\n- Manuales y garantías de equipos e instalaciones comunes.\n- Plan de emergencia y evacuación, con constancias de recepción de Carabineros y Bomberos.\n- Contratos vigentes de servicios y listado de proveedores y subcontratistas de especialidades.\n- Registro de compradores / estado de venta de las unidades.\n- Dotación de personal prevista y calendario estimado de entregas.\n\nEsta información es clave para identificar brechas y que la comunidad inicie su operación con sus antecedentes en regla. Quedamos atentos a lo que nos puedan compartir según vayan teniendo disponibilidad.\n\nUn cordial saludo.","sugerida":false,"variantes":[]},{"codigo":"21","nombre":"Visita y levantamiento en terreno","categoria":"Cierre y puesta en marcha","uso":"coordinar la visita del jefe zonal.","etapa_crm":"Diagnóstico / Puesta en marcha","adjunto_sugerido":"","asunto":"Re: [asunto original] — o — Visita en terreno {{comunidad}}","cuerpo":"{{saludo}} {{nombre}}:\n\nJunto con saludar, proponemos coordinar la visita y levantamiento en terreno de {{comunidad}}.\n\nLa visita será realizada por nuestro jefe zonal, {{jefe_zonal}}, quien asistirá en representación de Coproactiva.\n\nPropuesta: {{fecha}} a las {{hora}}.\n\nPara organizarla, le agradeceríamos indicarnos el nombre y datos de contacto de la persona que lo recibirá en la comunidad.\n\nQuedamos a vuestra disposición.\n\nSaludos cordiales.","sugerida":false,"variantes":[]},{"codigo":"22","nombre":"Inicio de gestión y reunión de arranque","categoria":"Cierre y puesta en marcha","uso":"se recibe la designación o se firma el contrato.","etapa_crm":"Cliente activo","adjunto_sugerido":"","asunto":"Re: [asunto original] — o — Inicio de administración {{comunidad}}","cuerpo":"{{saludo}} {{nombre}}:\n\nJunto con saludar, le confirmamos que recibimos {{documento_recibido}} [Ej.: la escritura de designación] y estamos muy contentos de comenzar a trabajar en {{comunidad}}.\n\nPara partir, proponemos una reunión {{modalidad}} el {{fecha}} a las {{hora}}, donde veremos:\n\n1. Calendario de entrega de unidades.\n2. Método de trabajo.\n3. Financiamiento inicial.\n4. Documentación pendiente.\n5. Contraparte para la coordinación.\n\nMientras tanto, iremos adelantando lo administrativo: trámites ante el SII, cuenta bancaria de la comunidad, recorrido de bienes comunes, acta de condiciones y cotizaciones.\n\nCualquier contratación, gasto, seguro o movimiento de fondos lo haremos solo una vez validado y firmado el contrato.\n\n¿Le acomoda la fecha? Cuéntenos también quiénes se conectarán.\n\nUn cordial saludo.","sugerida":false,"variantes":[]},{"codigo":"23","nombre":"Solicitud de datos para trámite","categoria":"Cierre y puesta en marcha","uso":"un trámite (SII, banco, municipalidad) exige datos que debe entregar el cliente.","etapa_crm":"Puesta en marcha","adjunto_sugerido":"","asunto":"Re: [asunto original]","cuerpo":"{{saludo}} {{nombre}}:\n\nJunto con saludar, y con el fin de avanzar en {{tramite}} [Ej.: la obtención del RUT de la comunidad ante el SII], el sistema requiere {{requisito}} [Ej.: registrar los datos de una persona natural en la sección de Directiva].\n\nPor ello, le agradeceríamos enviarnos:\n\n- {{dato_1}}\n- {{dato_2}}\n\nCon esta información podremos completar el trámite a la brevedad.\n\nQuedamos a vuestra disposición.\n\nSaludos cordiales,","sugerida":false,"variantes":[]},{"codigo":"24","nombre":"Informe de avance","categoria":"Gestión y avances","uso":"semanal o quincenal durante puesta en marcha; mensual con cliente activo.","etapa_crm":"Cliente activo","adjunto_sugerido":"","asunto":"Avance {{comunidad}} — {{periodo}}","cuerpo":"{{saludo}} {{nombre}}:\n\nJunto con saludar, compartimos el estado de la gestión de {{comunidad}} al {{fecha}}.\n\nRealizado:\n- {{realizado_1}}\n- {{realizado_2}}\n\nEn curso:\n- {{en_curso_1}} — responsable: {{responsable}} — plazo: {{plazo}}\n\nPendiente de su parte:\n- {{pendiente_cliente_1}}\n\nPróximos pasos:\n- {{proximo_1}}\n\n[Si aplica] Adjuntamos {{documentos}} para su revisión.\n\nQuedamos a vuestra disposición ante cualquier consulta.\n\nSaludos cordiales,","sugerida":true,"variantes":[]},{"codigo":"25","nombre":"Seguimiento a propuesta sin respuesta","categoria":"Gestión y avances","uso":"5 a 7 días hábiles después de enviar la propuesta. Responder en el mismo hilo.","etapa_crm":"Propuesta enviada → Seguimiento 1","adjunto_sugerido":"","asunto":"Re: [asunto de la propuesta]","cuerpo":"{{saludo}} {{nombre}}:\n\nJunto con saludar, le escribo para saber si han podido revisar la propuesta que les enviamos el {{fecha_envio}} para {{comunidad}}.\n\nSi surgieron dudas o desean ajustar algún punto del alcance, con gusto lo revisamos en una reunión breve {{modalidad}}. Tenemos disponibilidad {{disponibilidad}}.\n\nQuedamos a vuestra disposición.\n\nUn cordial saludo.","sugerida":true,"variantes":[]},{"codigo":"26","nombre":"Seguimiento a documentación pendiente","categoria":"Gestión y avances","uso":"cuando un documento solicitado bloquea un paso (contrato, RUT, cuenta, entrega).","etapa_crm":"Puesta en marcha","adjunto_sugerido":"","asunto":"Re: [asunto original]","cuerpo":"{{saludo}} {{nombre}}:\n\nJunto con saludar, le recordamos que para avanzar con {{paso_bloqueado}} aún necesitamos:\n\n- {{documento_1}}\n- {{documento_2}}\n\nSi alguno de estos antecedentes no está disponible, le agradeceríamos indicarnos quién podría facilitarlo o en qué plazo estiman contar con él, para ajustar el calendario.\n\nQuedamos a vuestra disposición.\n\nSaludos cordiales,","sugerida":true,"variantes":[]},{"codigo":"27","nombre":"Consulta de cobertura","categoria":"Proveedores","uso":"primer contacto con proveedores para armar la base por zona.","etapa_crm":"Proveedor → Contactado","adjunto_sugerido":"","asunto":"Consulta de servicios — Coproactiva","cuerpo":"{{saludo}} {{nombre}}:\n\nJunto con saludar, le escribimos desde Coproactiva, empresa de administración de edificios y condominios.\n\nEstamos evaluando proveedores de {{rubro}} para comunidades que administramos en {{zonas}} [Ej.: Santiago y Coquimbo–La Serena]. ¿Podría indicarnos si cuentan con cobertura en esas zonas?\n\nDe ser así, le agradeceríamos enviarnos su presentación o catálogo de servicios.\n\nQuedamos a vuestra disposición.\n\nSaludos cordiales,","sugerida":false,"variantes":[]},{"codigo":"28","nombre":"Solicitud de cotización de servicio","categoria":"Proveedores","uso":"necesidad concreta en una comunidad administrada (conserjería, áreas verdes, portón, mantención, etc.).","etapa_crm":"Proveedor → Cotización solicitada","adjunto_sugerido":"","asunto":"Cotización {{servicio}} – {{comunidad}}, {{comuna}}","cuerpo":"Estimados:\n\nJunto con saludar, les escribimos desde Coproactiva, administración de {{comunidad}} ({{direccion}}, {{comuna}}). Es un condominio de {{unidades}} con {{caracteristicas}} [Ej.: caseta de acceso, portón vehicular eléctrico y acceso peatonal]. {{contexto_fecha}} [Ej.: Las primeras entregas comienzan en la primera quincena de noviembre.]\n\nSolicitamos cotización de los siguientes servicios:\n\n- {{servicio_1}}: {{detalle_1}} [Ej.: conserje diurno en caseta, de lunes a domingo, 08:00 a 20:00 horas.]\n- {{servicio_2}}: {{detalle_2}}\n\nLes pedimos valorizar {{forma_valorizacion}} [Ej.: ambos servicios por separado y en conjunto], indicando {{datos_requeridos}} [Ej.: dotación, sistema de turnos, supervisión, reemplazos y valor mensual neto].\n\nSi requieren conocer la comunidad antes de cotizar, nuestro jefe zonal, {{jefe_zonal}}, puede recibirlos en terreno a partir del {{fecha}}.\n\nQuedamos a vuestra disposición.","sugerida":false,"variantes":[]},{"codigo":"29","nombre":"Respuesta a presentación de proveedor","categoria":"Proveedores","uso":"un proveedor se presenta y hay una necesidad vigente para la que podría cotizar.","etapa_crm":"Proveedor → Cotización solicitada","adjunto_sugerido":"","asunto":"Re: [asunto original]","cuerpo":"{{saludo}} {{nombre}}:\n\nJunto con saludar, agradecemos su presentación. Actualmente administramos {{comunidad}} ({{direccion}}, {{comuna}}), de {{unidades}}. ¿Cuentan con cobertura en {{comuna}}?\n\nDe ser así, solicitamos cotización de:\n\n- {{servicio_1}}: {{detalle_1}}\n- {{servicio_2}}: {{detalle_2}}\n\nLes pedimos indicar {{datos_requeridos}} y valor mensual neto.\n\nSi requieren conocer la comunidad antes de cotizar, nuestro jefe zonal, {{jefe_zonal}}, puede recibirlos en terreno.\n\nQuedamos a vuestra disposición.","sugerida":false,"variantes":[]},{"codigo":"30","nombre":"Aclaración por envío erróneo","categoria":"Proveedores","uso":"un correo salió sin contexto, duplicado o por error de automatización.","etapa_crm":"—","adjunto_sugerido":"","asunto":"Re: [asunto original]","cuerpo":"{{saludo}} {{nombre}}:\n\nMuchas gracias por su pronta respuesta.\n\nLe comento que nuestro correo anterior se envió por error {{motivo}} [Ej.: a través de una automatización], por lo que le llegó sin mayor contexto. Le pedimos disculpas por la confusión.\n\n{{continuacion}} [Ej.: Independiente de ello, por nuestro rubro igualmente nos serviría contar con un catálogo de sus productos y servicios.]\n\nUn cordial saludo.","sugerida":false,"variantes":[]},{"codigo":"31","nombre":"Oferta laboral a OMIL o bolsa de empleo","categoria":"Personal","uso":"contratación directa de personal para una comunidad.","etapa_crm":"Reclutamiento","adjunto_sugerido":"","asunto":"Oferta laboral {{cargos}} – {{comunidad}}, {{comuna}}","cuerpo":"Estimados:\n\nJunto con saludar, desde Coproactiva, administración de {{comunidad}} ({{direccion}}, {{comuna}}), buscamos contratar directamente personal a partir de {{fecha_inicio}}:\n\n- {{cargo_1}}, {{horario_1}}, turno {{turno_1}}: {{vacantes_1}} vacantes. Requisitos: {{requisitos_1}}.\n- {{cargo_2}}, {{horario_2}}, turno {{turno_2}}: {{vacantes_2}} vacantes. Requisitos: {{requisitos_2}}.\n\nLa renta se informará en la entrevista, según experiencia.\n\nLes agradeceremos difundir la oferta y remitir los currículums a contacto@coproactiva.cl.\n\nQuedamos a vuestra disposición.","sugerida":false,"variantes":[]},{"codigo":"32","nombre":"Respuesta a postulación con vacante","categoria":"Personal","uso":"llega una postulación espontánea y hay vacante abierta.","etapa_crm":"Reclutamiento → Postulante","adjunto_sugerido":"","asunto":"Re: [asunto original]","cuerpo":"{{saludo}} {{nombre}}:\n\nJunto con saludar, agradecemos su postulación. Actualmente tenemos vacantes de {{cargo}} en una comunidad en {{comuna}}.\n\n¿Podría indicarnos su comuna de residencia, su disponibilidad para trabajar en {{comuna}} y si cuenta con {{requisito}} [Ej.: curso OS-10 vigente]?\n\nQuedamos a vuestra disposición.","sugerida":false,"variantes":[]},{"codigo":"33","nombre":"Respuesta a postulación sin vacante","categoria":"Personal","uso":"postulación espontánea sin vacante disponible.","etapa_crm":"Reclutamiento → Banco de candidatos","adjunto_sugerido":"","asunto":"Re: [asunto original]","cuerpo":"{{saludo}} {{nombre}}:\n\nJunto con saludar, agradecemos su interés en trabajar con Coproactiva.\n\nPor el momento no tenemos vacantes disponibles para {{cargo}}. Dejaremos sus antecedentes registrados y lo contactaremos si se abre un proceso que se ajuste a su perfil.\n\nQuedamos a vuestra disposición.","sugerida":true,"variantes":[]}]'::jsonb) as x(
 codigo text,nombre text,categoria text,uso text,etapa_crm text,adjunto_sugerido text,
 asunto text,cuerpo text,sugerida boolean,variantes jsonb
)
on conflict (codigo) do nothing;

